@six.add_metaclass(ABCMeta)
class UE(object):
    def __init__(self, imsi=None, sec_key=None, mcs_ports=None):
        # type: (Optional[str], Optional[str], Optional[List[MCSPort]]) -> None
        """

        :param Optional[str] imsi:  Optional[str] imsi value that UE presents to BTS
        :param Optional[str] sec_key:  Optional[str] security key value that UE presents to BTS
        :param Optional[List[MCSPort]] mcs_ports: mcs ports connected to UE
        """
        self.imsi = imsi
        self.sec_key = sec_key
        self.mcs_ports = mcs_ports or []


class Prisma(UE):
    def __init__(self,
                 airmosaic_ssh_connection_details,            # type: SshServiceDetails
                 airmosaic_harness_connection_details,        # type: HttpConnectionDetails
                 lsu_uu_ssh_connection_details,               # type: SshServiceDetails
                 tstm_uu_ssh_connection_details,              # type: SshServiceDetails
                 prisma_config_file=None,                     # type: Optional[str]
                 default_sid_file=None,                       # type: Optional[str]
                 iperf_details=None,                          # type: Optional[IperfDataTransferDetails]
                 imsi=None,                                   # type: Optional[str]
                 sec_key=None,                                # type: Optional[str]
                 gnb_common_unit_for_throughput_check=None,   # type: Optional[CommonUnit]
                 capabilities=None,                           # type: Optional[List[str]]
                 channel_emulator_ports=None,                 # type: Optional[List[ChannelEmulatorPort]]
                 mcs_ports=None                               # type: Optional[List[MCSPort]]
                 ):
        # type: (...) -> None
        """
        :param SshServiceDetails airmosaic_ssh_connection_details:  SshServiceDetails class instance object
        :param HttpConnectionDetails airmosaic_harness_connection_details:  HttpConnectionDetails class instance object
        :param SshServiceDetails lsu_uu_ssh_connection_details:  SshServiceDetails class instance object
        :param SshServiceDetails tstm_uu_ssh_connection_details:  SshServiceDetails class instance object
        :param prisma_config_file str: (optional) path to the .yml file that is expected by taf.ue.prisma
        The file should be stored in the testline configuration directory.
        a sample file can be referred to the link:
        https://confluence.int.net.nokia.com/pages/viewpage.action?pageId=756292289#Prismasample-Sample.1
        :param default_sid_file: (optional) sid file path,
        note: the sid file need be in a folder which contains all the script files the airmosaic required,
        such as *.sid, *.sce, *.usr *.mdl
        :param Optional[str] imsi:  Optional[str] imsi value that UE presents to BTS
        :param Optional[str] sec_key:  Optional[str] security key value that UE presents to BTS
        :param gnb_common_unit_for_throughput_check: Optional[CommonUnit] gNB common unit for check gnb l2 low throughput
        :param list capabilities: Capabilities that UE has, defaults to None.
        :param Optional[List[ChannelEmulatorPort]]: ports of channel emulator connected to the UE
        :param Optional[List[MCSPort]] mcs_ports: mcs ports connected to UE
        As a Prisma UE, when translated to ute_ue, capabilities 'PRISMA_UE' is always added.
        """
        super(Prisma, self).__init__(imsi, sec_key, mcs_ports=mcs_ports)
        self.airmosaic_ssh_connection_details = airmosaic_ssh_connection_details
        self.airmosaic_harness_connection_details = airmosaic_harness_connection_details
        self.lsu_uu_ssh_connection_details = lsu_uu_ssh_connection_details
        self.tstm_uu_ssh_connection_details = tstm_uu_ssh_connection_details
        self.prisma_config_file = prisma_config_file
        self.default_sid_file = default_sid_file
        self.iperf_details = iperf_details
        self.gnb_common_unit_for_throughput_check = gnb_common_unit_for_throughput_check
        self.channel_emulator_ports = channel_emulator_ports
        self.capabilities = capabilities


class LicenseKeeper(object):
    def __init__(self, username, password):
        # type: (str, str) -> None
        """
        :param str username: username to login license keeper server
        :param str password: password to login license keeper server
        """
        self.username = username
        self.password = password


class Qualcomm(UE):
    def __init__(self,
                 ssh_connection_details,       # type: SshServiceDetails
                 serial_number,                # type: str
                 qxdm_version,                 # type: int
                 ue_type,                      # type: QualcommUeType
                 com_port,                     # type: int
                 heartbeat_port,               # type: int
                 server_command_input_port,    # type: int
                 server_qxdm_messages_port,    # type: int
                 server_command_output_port,   # type: int
                 message_stream_port,          # type: int
                 iperf_details=None,           # type: Optional[IperfDataTransferDetails]
                 imsi=None,                    # type: Optional[str]
                 sec_key=None,                 # type: Optional[str]
                 pdu_port=None,                # type: Optional[PduPort]
                 capabilities=None,            # type: Optional[List[str]]
                 licensekeeper=None,           # type: Optional[LicenseKeeper]
                 channel_emulator_ports=None,  # type: Optional[List[ChannelEmulatorPort]]
                 license_type=None,            # type: Optional[QualcommLicenseType]
                 mcs_ports=None                # type: Optional[List[MCSPort]]
                 ):
        # type: (...) -> None
        """

        :param SshServiceDetails ssh_connection_details: credentials/addresses for UE PC
        :param str serial_number: UE serial number (visible in adb devices)
        :param int qxdm_version: QXDM app version to be used
        :param QualcommUeType ue_type: determines way of data transfer handling:
            android - iperf on ue,
            linux - iperf on UE_PC, use of QMICM, UE as a modem
        :param int com_port: COM port UE diagnostic interface is assigned to
        :param int heartbeat_port: port for heartbeat messages
        :param int server_command_input_port: Port for command input
        :param int server_qxdm_messages_port: Port for QXDM messages output
        :param int server_command_output_port: Port for server command output
        :param int message_stream_port: Port for RRC messages stream
            (source for ta_messsaging), requires ue_pc_server started with
            message stream
        :param IperfDataTransferDetails iperf_details: (optional) information required in
            data transfer scenarios to start iperf
        :param Optional[str] imsi: imsi value that UE presents to BTS
        :param Optional[str] sec_key: security key value that UE presents to BTS
        :param Optional[PduPort] pdu_port: PduPort for power reset
        :param list capabilities: Capabilities that UE has, defaults to None.
            As a Qualcomm UE, when translated to ute_ue, capabilities 'REAL_UE' and
            'REAL_QUALCOMM_UE' are always added.
        :param licensekeeper: license keeper information required when using QXDM/QCAT
        :param Optional[QualcommLicenseType] license_type: which QXDM license [4G, 5G] should be obtained for the UE
        :param Optional[List[ChannelEmulatorPort]] channel_emulator_ports: ports of channel emulator connected to the UE
        :param Optional[List[MCSPort]] mcs_ports: mcs ports connected to UE
        """
        super(Qualcomm, self).__init__(imsi, sec_key, mcs_ports=mcs_ports)
        self.ssh_connection_details = ssh_connection_details
        self.iperf_details = iperf_details
        self.serial_number = serial_number
        self.qxdm_version = qxdm_version
        self.ue_type = ue_type
        self.com_port = com_port
        self.heartbeat_port = heartbeat_port
        self.server_command_input_port = server_command_input_port
        self.server_qxdm_messages_port = server_qxdm_messages_port
        self.server_command_output_port = server_command_output_port
        self.message_stream_port = message_stream_port
        self.pdu_port = pdu_port
        self.channel_emulator_ports = channel_emulator_ports
        self.capabilities = capabilities
        self.licensekeeper = licensekeeper
        self.license_type = license_type

    def __taf_contract_ssh__(self):
        return self.ssh_connection_details.__taf_contract_ssh__()


