class MediaTek(UE):
    def __init__(self,
                 ssh_connection_details,        # type: SshServiceDetails
                 server_dir,                    # type: str
                 server_port,                   # type: int
                 edb_file_path,                 # type: str
                 imei,                          # type: str
                 apn_url,                       # type: str
                 iperf_details=None,            # type: Optional[IperfDataTransferDetails]
                 imsi=None,                     # type: Optional[str]
                 sec_key=None,                  # type: Optional[str]
                 com_port=None,                 # type: Optional[str]
                 python_path=None,              # type: Optional[str]
                 log_filter=None,               # type: Optional[str]
                 capabilities=None,             # type: Optional[List[str]]
                 channel_emulator_ports=None,   # type: Optional[List[ChannelEmulatorPort]]
                 serial_number=None,            # type: Optional[str]
                 mcs_ports=None                 # type: Optional[List[MCSPort]]
                 ):
        # type: (...) -> None
        """

        :param SshServiceDetails ssh_connection_details: credentials/addresses for UE PC
        :param str server_dir: path to directory on UE PC where pyro server will be copied
        :param int server_port: port to connect the pyro server
        :param str edb_file_path: edb file path on the UE PC
        :param str imei: imei value to identify the UE
        :param apn_url: access point name, DDN in EPS
        :param IperfDataTransferDetails iperf_details: (optional) information required in
            data transfer scenarios to start iperf
        :param Optional[str] imsi: imsi value that UE presents to BTS
        :param Optional[str] sec_key: security key value that UE presents to BTS
        :param Optional[str] com_port: COM port of UE for management and log diagnostic,
            default will be "auto" which is used in "Apollo" and "Petrus", "4" is an option used for "Oppo" MTK UE
        :param Optional[str] python_path: path to python binary on UE PC,
            if leave it alone, will use the python defined in $PATH
        :param Optional[str] log_filter: OPTIONAL filter for OTA message identification
        :param list capabilities: Capabilities that UE has, defaults to None.
            As an MediaTek UE, when translated to ute_ue, capabilities 'REAL_UE' and
            'REAL_MEDIATEK_UE' are always added.
        :param Optional[List[ChannelEmulatorPort]]: ports of channel emulator connected to the UE
        :param Optional[str] serial_number: UE serial number (visible in adb devices)
        :param Optional[List[MCSPort]] mcs_ports: mcs ports connected to UE
        """
        super(MediaTek, self).__init__(imsi, sec_key, mcs_ports=mcs_ports)
        self.ssh_connection_details = ssh_connection_details
        self.server_dir = server_dir
        self.server_port = server_port
        self.edb_file_path = edb_file_path
        self.imei = imei
        self.apn_url = apn_url
        self.iperf_details = iperf_details
        self.com_port = com_port or "auto"
        self.python_path = python_path
        self.log_filter = log_filter
        self.channel_emulator_ports = channel_emulator_ports
        self.capabilities = capabilities
        self.serial_number = serial_number

    def __taf_contract_ssh__(self):
        return self.ssh_connection_details.__taf_contract_ssh__()


