class PreferredVlan(object):
    def __init__(self, slot_id, port_id, preferred_vlan_id):
        # type: (SlotId, int, int) -> None
        """
        :param SlotId slot_id: id of slot where capacity unit is placed, one of SlotId

                                          AMIA
                              ___________________________
                             |      B3     |     B6      |
                             |_____________|_____________|
                             |      B2     |     B5      |
                             |_____________|_____________|
                             |      B1     |     B4      |
                             |_____________|_____________|
                             |      C1     |     C2      |
                             |_____________|_____________|

        :param int port_id: id of RF port on the capacity unit described by slot_id (e.g. 1-9 for ABIO)

                                          ABIO
             _______________________________________________________________________
            |  RF1  |  RF2  |  RF3  |  RF4  |  RF5  |  RF6  |  RF7  |  RF8  |  RF9  |
            |_______|_______|_______|_______|_______|_______|_______|_______|_______|

                                        EXAMLE MAPPING
                         _______________________________________
                        |  <physicalId>  |  slot_id  | port_id  |
                        |   in iphy.xml  |           |          |
                        |________________|___________|__________|
                        |      1.1       |    B1     |    1     |
                        |________________|___________|__________|
                        |      2.3       |    B2     |    3     |
                        |________________|___________|__________|

        :param int preferred_vlan_id: preferred VLAN identifier defined in Airphone configuration file (iphy.xml)
        """
        self.slot_id = slot_id
        self.port_id = port_id
        self.preferred_vlan_id = preferred_vlan_id


class Airphone(UE):
    """Based on "Airphone Product and SW Architecture (5G18A) 0.4 (draft)"""
    DEFAULT_L3_PORT = 7777

    def __init__(self, egate,                    # type: SshServiceDetails
                 l3_ssh_connection_details,      # type: SshServiceDetails
                 l2_ssh_connection_details,      # type: SshServiceDetails
                 l1,                             # type: Airscale
                 airphone_cloud=None,            # type: Optional[AirphoneCloud]
                 deployment_configuration=None,  # type: Optional[str]
                 l3_port=None,                   # type: Optional[int]
                 edaemon_port=None,              # type: Optional[int]
                 egate_port=None,                # type: Optional[int]
                 imsi=None,                      # type: Optional[str]
                 sec_key=None,                   # type: Optional[str]
                 preferred_vlan_id=None,         # type: Optional[int]
                 preferred_vlans=None,           # type: Optional[List[PreferredVlan]]
                 mcs_ports=None                  # type: Optional[List[MCSPort]]
                 ):
        # type: (...) -> None
        """

        :param SshServiceDetails egate: SshServiceDetails class instance object
        :param SshServiceDetails l3_ssh_connection_details: SshServiceDetails class instance object
        :param SshServiceDetails l2_ssh_connection_details: SshServiceDetails class instance object
        :param Airscale l1: Airscale class instance object
        :param Optional[AirphoneCloud] airphone_cloud: AirphoneCloud class instance object
        :param Optional[str] deployment_configuration:(A,B,C,D0....) based on 5.4. Currently supported configuration = C
        :param Optional[int] l3_port: l3 port used when running l3, default 7777
        :param Optional[int] edaemon_port: edaemon port used when running edaemon
        :param Optional[int] egate_port: egate port used when running egate
        :param Optional[str] imsi: imsi value that UE presents to BTS
        :param Optional[str] sec_key: security key value that UE presents to BTS
        :param Optional[int] preferred_vlan_id: DEPRECATED preferred VLAN identifier defined in Airphone configuration file (iphy.xml).
            Use preferred_vlans instead
        :param Optional[List[PreferredVlan]] preferred_vlans: list of a preferred VLAN identifiers
            defined in Airphone configuration file (iphy.xml)
        :param Optional[List[MCSPort]] mcs_ports: mcs ports connected to UE
        """
        super(Airphone, self).__init__(imsi, sec_key, mcs_ports=mcs_ports)
        self.egate = egate
        self.l2_ssh_connection_details = l2_ssh_connection_details
        self.l3_ssh_connection_details = l3_ssh_connection_details
        self.l1 = l1
        self.edaemon_port = edaemon_port
        self.egate_port = egate_port
        self.l3_port = l3_port or self.DEFAULT_L3_PORT
        self.airphone_cloud = airphone_cloud
        self.deployment_configuration = deployment_configuration or "C"
        self.preferred_vlan_id = preferred_vlan_id
        self.preferred_vlans = preferred_vlans

        if self.preferred_vlan_id:
            logging.warning('The preferred_vlan_id parameter is deprecated and will be removed in the future. '
                            'Please use preferred_vlans as a list of PreferredVlan objects instead.')


